content:
{
  "initial_state": "home_ready",
  "states": [
    {
      "id": "home_ready",
      "description": "Robot monitors home environment before the person arrives.",
      "rules": [
        {
          "trigger": "air conditioner · off, indoor temperature 29°C · caused by: device",
          "action": "Turn on air conditioner and set temperature to 26°C"
        }
      ],
      "next": [
        {
          "to": "arrival_settling",
          "on": "The person enters through the front door"
        }
      ]
    },
    {
      "id": "arrival_settling",
      "description": "Person settles in, retrieves drinks, and manages immediate appliances.",
      "rules": [
        {
          "trigger": "The person sits on the sofa",
          "action": "Go to refrigerator, open door, pick cola, place cola on side table, close door"
        },
        {
          "trigger": "refrigerator · door has been open for 1 minute · caused by: device",
          "action": "Close refrigerator door"
        },
        {
          "trigger": "washing machine · cycle finished · caused by: device",
          "action": "Open washing machine, pick laundry, place laundry inside dryer, close dryer, start dryer"
        }
      ],
      "next": [
        {
          "to": "post_laundry_idle",
          "on": "washing machine · cycle finished · caused by: device"
        }
      ]
    },
    {
      "id": "post_laundry_idle",
      "description": "Period between laundry completion and evening snack preparation.",
      "rules": [],
      "next": [
        {
          "to": "snack_cleanup",
          "on": "refrigerator · door opened · caused by: user"
        }
      ]
    },
    {
      "id": "snack_cleanup",
      "description": "Person prepares a snack and cleans up dishes.",
      "rules": [
        {
          "trigger": "Empty cup is on the kitchen counter",
          "action": "Pick cup from kitchen counter, place cup inside dishwasher, close dishwasher door"
        }
      ],
      "next": []
    }
  ]
}
